#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    string name;
    Cat(const string& n) : name(n) {}
    virtual ~Cat() {}
};

class OrangeCat : public Cat {
public:
    OrangeCat(const string& n) : Cat(n) {}
};

int main() {
    OrangeCat o("{who}");
    Cat* p = &o;
    OrangeCat* a = dynamic_cast<OrangeCat*>(p);
    cout << (a == nullptr ? "照不出来" : "照出来了：" + a->name) << endl;
    return 0;
}
